function applySimulatedFailure(jobId: string, attempt: number): void {
  if (attempt < MAX_ATTEMPTS) requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), jobId);
  else fail.run(nowIso(), jobId);
}

/**
 * Handles jobs left `running` by a worker that died. Their current attempt was started but never
 * finished, so `attempts` already counts it:
 * - an interrupted simulated failure (attempts <= failAttempts) would have failed, so its failure
 *   outcome is applied and the retry limit still holds;
 * - an interrupted successful attempt is requeued and processed again from the start.
 */
function recoverRunning(): void {
  for (const job of runningJobs.all() as unknown as JobRow[]) {
    if (job.attempts <= job.fail_attempts) {
      applySimulatedFailure(job.id, job.attempts);
    } else {
      requeueInterrupted.run(nowIso(), job.id);
    }
  }
}

