  return {
    id: row.id,
    status: row.status,
    input: JSON.parse(row.input_json) as string,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result:
      row.status === 'completed' && row.result_json !== null
        ? { output: JSON.parse(row.result_json) as string }
        : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function mediaType(req: IncomingMessage): string {
  const value = req.headers['content-type'];
  return typeof value === 'string' ? value.split(';')[0].trim().toLowerCase() : '';
