  const input = body.input;
  const steps = body.steps === undefined ? 5 : body.steps;
  const failAttempts = body.failAttempts === undefined ? 0 : body.failAttempts;
  if (typeof input !== 'string' || input.length < 1 || input.length > 1000 || input.trim() === '') {
    fields.push({ field: 'input', message: 'must be a string of 1 to 1000 characters that is not only whitespace' });
  }
  if (!isIntIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
  if (!isIntIn(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
  if (fields.length > before || typeof input !== 'string' || !isIntIn(steps, 1, 20) || !isIntIn(failAttempts, 0, 5)) return undefined;
  return { input, steps, failAttempts };
}

function sameSubmission(job: JobRow, sub: Submission): boolean {
